#pragma once
//
// "Cockpit" main screen, airliner radio panel style (two stacked units). The panel, knobs, buttons and the
// 7-segment glyph masks are pre-rendered with anti-aliasing (Cockpit737Art.h, generated by gen737.py); this
// code only composes the dynamic parts: digits, lamps, bar graphs and a few texts.
// Header-only (also used by the PC preview).
//
#include "CockpitUI.h"
#include "AnalogUI.h"
#include "Cockpit737Art.h"

namespace bx
{
  static inline uint16_t rgb(int r, int g, int b) { return (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)); }

  struct GlyphSet { int w, h; const uint8_t *ghost; const uint8_t *const *lit; const uint8_t *dot; };
  static const GlyphSet gsA = {BX_A_W, BX_A_H, BX_A_G, BX_A_L, BX_A_DOT};
  static const GlyphSet gsB = {BX_B_W, BX_B_H, BX_B_G, BX_B_L, BX_B_DOT};
  static const GlyphSet gsC = {BX_C_W, BX_C_H, BX_C_G, BX_C_L, BX_C_DOT};

  // One digit cell: ghost segments plus the lit ones, blended over black. digit < 0 = blank
  template<class G>
  static void glyph(G &g, const GlyphSet &gs, int x, int y, int digit, uint16_t on, uint16_t off)
  {
    const uint8_t *lit = (digit >= 0 && digit <= 9) ? gs.lit[digit] : nullptr;
    for(int yy = 0 ; yy < gs.h ; yy++)
      for(int xx = 0 ; xx < gs.w ; xx++)
      {
        const int i = yy * gs.w + xx;
        const int gm = pgm_read_byte(gs.ghost + i), lm = lit ? pgm_read_byte(lit + i) : 0;
        if(!gm && !lm) continue;
        uint16_t col = ckMix(0x0000, off, gm);
        if(lm) col = ckMix(col, on, lm);
        g.drawPixel(x + xx, y + yy, col);
      }
  }

  // Draws a numeric string such as "103.900" into 'cells' cells; '.' attaches after cell dotAt (-1 = none)
  template<class G>
  static void number(G &g, const GlyphSet &gs, const char *s, int cells, int dotAt, int x0, int y, int pitch, int cw, int ch, uint16_t on, uint16_t off)
  {
    int digs[12], n = 0;
    bool hasDot = false;
    for(const char *p = s ; *p && n < 12 ; p++)
    {
      if(*p == '.') hasDot = true;
      else digs[n++] = (*p >= '0' && *p <= '9') ? *p - '0' : -1;
    }
    for(int i = 0 ; i < cells ; i++)
    {
      const int src = i - (cells - n);
      glyph(g, gs, x0 + i * pitch, y, src >= 0 ? digs[src] : -1, on, off);
      if(dotAt >= 0 && i == dotAt)
        for(int yy = 0 ; yy < 4 ; yy++) for(int xx = 0 ; xx < 4 ; xx++)
        {
          const int m = pgm_read_byte(gs.dot + yy * 4 + xx);
          g.drawPixel(x0 + i * pitch + cw + 1 + xx, y + ch - 3 + yy, ckMix(ckMix(0, off, 255), on, hasDot ? m : 0) );
        }
    }
  }

  static inline uint16_t bgPix(int x, int y) { return pgm_read_word(BX_BG + y * 320 + x); }
}

template<class G>
static void bxDraw(G &g, const CkIn &in, const CkColors &c, bool /*unused*/, float sV, float nV)
{
  const uint16_t amber = bx::rgb(255, 150, 40), white = bx::rgb(238, 240, 248);
  const uint16_t digOn = bx::rgb(244, 248, 255), digOff = bx::rgb(30, 34, 50);

  g.pushImage(0, 0, 320, 170, (const lgfx::rgb565_t *)BX_BG);

  // The top-right banner (Wi-Fi, battery) would cover the STANDBY label of the art: repaint it as a shorter label at the left
  for(int y = 2 ; y < 16 ; y++) g.drawFastHLine(219, y, 59, (uint16_t)BX_BG[y * 320 + 216]);
  ckText(g, FontB612Bold12, "STBY", 205, 3, amber, 1);

  // ---- ACTIVE / STANDBY ----
  auto freqStr = [&](uint32_t f, char *s, size_t n) {
    if(in.mode == 0) snprintf(s, n, "%u.%03u", (unsigned)(f / 1000000), (unsigned)((f % 1000000) / 1000));
    else snprintf(s, n, "%u.%03u", (unsigned)(f / 1000), (unsigned)(f % 1000));
  };
  const bool fm = in.mode == 0;
  const bx::GlyphSet &gs = fm ? bx::gsA : bx::gsB;
  const int ncell = fm ? 6 : 8, dotAt = fm ? 2 : 4;
  const int cw = fm ? 11 : 9, pitch = fm ? 19 : 14, ch = 21;
  const int wy = 17, wh = 29;
  char fs[16];
  freqStr(in.freq, fs, sizeof(fs));
  const int ax = 10 + (124 - ncell * pitch) / 2 + 2, ay = wy + 4;
  bx::number(g, gs, fs, ncell, dotAt, ax, ay, pitch, cw, ch, digOn, digOff);
  freqStr(in.stby ? in.stby : in.freq, fs, sizeof(fs));
  bx::number(g, gs, fs, ncell, dotAt, 186 + (124 - ncell * pitch) / 2 + 2, ay, pitch, cw, ch, digOn, digOff);
  if(in.hl != 100 && (in.hl & 0x7F) != 100)
  {
    const int hl = in.hl & 0x7F, slot = hl / 2;
    const int top = fm ? 4 : 7;
    if(slot <= top)
    {
      int c1 = top - slot, c0 = c1;
      if((hl & 1) && c0 > 0) c0--;
      g.fillRect(ax + c0 * pitch, wy + wh - 3, (c1 - c0) * pitch + cw + 1, 2, (in.hl & 0x80) ? 0xFFE0 : amber);
    }
  }

  // ---- Mode lamps ----
  const bool lit[6] = {in.mode == 0, in.mode == 1, in.mode == 2, in.mode == 3, in.stereo, in.station && in.station[0]};
  for(int i = 0 ; i < 6 ; i++)
    if(lit[i]) g.pushImage(74 + (i % 3) * 58 + 3 - 4, ((i / 3) ? 81 : 54) - 4, BX_LAMP_W, BX_LAMP_H, (const lgfx::rgb565_t *)BX_LAMP);

  // ---- Volume / step buttons and knob pointers ----
  char vol[8];
  if(in.volume < 0) snprintf(vol, sizeof(vol), "%s", uiText("MUTED")); else snprintf(vol, sizeof(vol), "%d", in.volume);
  ckText(g, FontB612Bold12, vol, 30, 60, white, 1);
  char st[10];
  snprintf(st, sizeof(st), "%s", in.step ? in.step : "");
  for(char *p = st ; *p ; p++) if(*p >= 'a' && *p <= 'z') *p -= 32;
  ckText(g, FontB612Bold12, st, 290, 60, white, 1);
  {
    float px, py;
    an::pol(30, 93, 8, (float)((in.volume < 0 ? 0 : in.volume) * 4), &px, &py);
    g.fillSmoothCircle((int)lroundf(px), (int)lroundf(py), 2, bx::rgb(110, 106, 94));
    an::pol(290, 93, 8, (float)((in.freq / 10000) % 36) * 10.0f, &px, &py);
    g.fillSmoothCircle((int)lroundf(px), (int)lroundf(py), 2, bx::rgb(110, 106, 94));
  }

  // ---- Lower unit ----
  if(in.station && in.station[0]) ckNameFit(g, FontB612Bold12, in.station, 92, 116, 136, white, 1);
  const int segs = 18, sp = 5;
  auto bargraph = [&](int x0, float v, bool isS)
  {
    const int on = (int)lroundf(v * segs);
    for(int i = 0 ; i < segs ; i++)
    {
      const bool red = isS && i >= segs * 28 / 49;
      const uint16_t litC = red ? bx::rgb(255, 80, 60) : digOn;
      const uint16_t offC = red ? bx::rgb(40, 12, 10) : bx::rgb(14, 16, 26);
      g.fillRect(x0 + i * sp, 135, 4, 10, i < on ? litC : offC);
    }
  };
  bargraph(15, sV, true);
  bargraph(191, nV, false);
  char b[6];
  snprintf(b, sizeof(b), "%02d", in.rssi > 99 ? 99 : (in.rssi < 0 ? 0 : in.rssi));
  bx::number(g, bx::gsC, b, 2, -1, 106, 134, 13, 8, 13, digOn, digOff);
  snprintf(b, sizeof(b), "%02d", in.snr > 99 ? 99 : (in.snr < 0 ? 0 : in.snr));
  bx::number(g, bx::gsC, b, 2, -1, 282, 134, 13, 8, 13, digOn, digOff);

  // Bandwidth / AGC (or attenuator) in the centre column
  char v[9];
  snprintf(v, sizeof(v), "%s", in.bw ? in.bw : "");
  for(char *p = v ; *p ; p++) if(*p >= 'a' && *p <= 'z') *p -= 32;
  ckText(g, FontB612Reg10, v, 158, 134, white);
  if(in.agcLabel && in.agcLabel[0] == 'A' && in.agcLabel[1] == 'T')
  {
    g.fillRect(141, 146, 22, 11, bx::bgPix(139, 150));
    ckText(g, FontB612Reg10, "ATT", 142, 148, amber);
  }
  snprintf(v, sizeof(v), "%s", in.agc ? in.agc : "");
  ckText(g, FontB612Reg10, v, 166, 148, white);
}
